package com.zhineng.platform.evaluation.selfevaluation.controller;
import com.zhineng.platform.evaluation.selfevaluation.dto.SelfEvaluationDtos.*;import com.zhineng.platform.evaluation.selfevaluation.service.SelfEvaluationService;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;import org.springframework.core.io.InputStreamResource;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/self-evaluations")public class SelfEvaluationController{
 private final SelfEvaluationService service;public SelfEvaluationController(SelfEvaluationService s){service=s;}
 @GetMapping("/options/indicator-versions")List<Map<String,Object>>versions(){return service.versions();}@GetMapping("/options/organizations")List<Map<String,Object>>orgs(){return service.orgs();}
 @GetMapping("/tasks")List<Map<String,Object>>tasks(){return service.tasks();}@GetMapping("/tasks/{id}")Map<String,Object>task(@PathVariable long id){return service.task(id);}
 @PostMapping("/tasks")@ResponseStatus(HttpStatus.CREATED)Map<String,Object>create(@RequestBody TaskRequest q){return service.createTask(q);}@PostMapping("/tasks/{id}/publish")Map<String,Object>publish(@PathVariable long id){return service.publish(id);}
 @PostMapping("/tasks/{id}/cancel")Map<String,Object>cancel(@PathVariable long id,@RequestBody ReviewRequest q){return service.cancel(id,q);}
 @GetMapping("/forms/{id}")Map<String,Object>form(@PathVariable long id){return service.form(id);}@PutMapping("/entries/{id}")Map<String,Object>entry(@PathVariable long id,@RequestBody EntryRequest q){return service.saveEntry(id,q);}
 @PostMapping("/forms/{id}/submit")Map<String,Object>submit(@PathVariable long id,@RequestBody(required=false)ReviewRequest q){return service.submit(id,q);}@PostMapping("/forms/{id}/review")Map<String,Object>review(@PathVariable long id,@RequestBody ReviewRequest q){return service.review(id,q);}
 @PutMapping("/indicator-snapshots/{id}/requirements")Map<String,Object>requirement(@PathVariable long id,@RequestBody RequirementRequest q){return service.requirement(id,q);}
 @PostMapping(value="/entries/{id}/materials",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)@ResponseStatus(HttpStatus.CREATED)Map<String,Object>upload(@PathVariable long id,@RequestPart("data")MaterialRequest q,@RequestPart("file")MultipartFile f){return service.upload(id,q,f);}
 @GetMapping("/entries/{id}/materials")List<Map<String,Object>>materials(@PathVariable long id){return service.materials(id);}@PutMapping("/materials/{id}/classification")Map<String,Object>classification(@PathVariable long id,@RequestBody Map<String,String>q){return service.confirmMaterial(id,q.get("category"));}@PutMapping("/materials/{id}/disable")Map<String,Object>disable(@PathVariable long id){return service.disableMaterial(id);}
 @GetMapping("/materials/{id}/download")ResponseEntity<InputStreamResource>download(@PathVariable long id)throws Exception{var f=service.download(id);HttpHeaders h=new HttpHeaders();h.setContentDisposition(ContentDisposition.attachment().filename(f.name(),StandardCharsets.UTF_8).build());h.setContentLength(Files.size(f.path()));try{h.setContentType(MediaType.parseMediaType(f.type()));}catch(Exception e){h.setContentType(MediaType.APPLICATION_OCTET_STREAM);}return new ResponseEntity<>(new InputStreamResource(Files.newInputStream(f.path())),h,HttpStatus.OK);}
 @PostMapping("/warning-runs")@ResponseStatus(HttpStatus.CREATED)Map<String,Object>run(@RequestParam long taskId,@RequestParam(required=false)Long orgUnitId){return service.runWarnings(taskId,orgUnitId);}@GetMapping("/warnings")List<Map<String,Object>>warnings(@RequestParam(required=false)Long runId){return service.warnings(runId);}
 @PutMapping("/warnings/{id}")Map<String,Object>process(@PathVariable long id,@RequestBody WarningProcessRequest q){return service.processWarning(id,q);}@PostMapping("/warnings/{id}/remind")Map<String,Object>remind(@PathVariable long id){return service.remind(id);}@GetMapping("/reminders")List<Map<String,Object>>reminders(){return service.reminders();}
}
